head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > maxByteLength]<br/>Textarea 컴포넌트에 입력 가능한 최대 바이트 길이를 설정합니다.",
    "validation" : [
        "입력 가능한 최대 바이트 길이를 양의 정수로 설정합니다.",
        "config.xml 의 WebSquare/byteCheckEncoding/@value 가 'euc-kr' 이면 한글 1자는 2바이트로 계산됩니다.",
        "값을 설정하지 않으면 '-1' 로 적용되어 입력을 제한하지 않습니다.",
        "입력값이 최대 바이트 길이에 도달하면 oneditfull 이벤트가 발생합니다.",
        "최대 바이트 길이를 초과하면 초과분이 자동으로 잘립니다.",
        "maxByteLength 와 maxlength 를 모두 설정하면 설정값이 작은 속성이 적용됩니다. (같은 값이면 maxByteLength 적용)",
        "validate() 메소드 실행 시 입력값의 Byte 수가 설정값보다 크면 유효성 체크는 실패로 처리되고 displaymessage 속성에 따라 실패 메시지가 출력됩니다.",
        "validate() 시스템 기본 메시지는 'n byte를 초과하여 입력할 수 없습니다.' 이며, invalidMessage 또는 invalidMessageFunc 속성으로 메시지를 변경할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function (target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (maxByteLength=6, 한글 EUC-KR 2바이트 → '가나다'=6byte PASS, 초과분 자동 자르기 확인)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바사");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}


// target2 (maxByteLength 미설정 → 입력 제한 없음, '-1' 로 동작)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바사아자차");
    target2.focus();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
}


// target3 (maxByteLength=6 + maxlength=10 → 작은 값 maxByteLength 적용)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나다라마바사");
    target3.focus();
};

scwin.btn_getText3_onclick = function (e) {
    scwin.get_text(target3);
}


// target4 (maxByteLength=10 + maxlength=3 → 작은 값 maxlength 적용)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("가나다라마");
    target4.focus();
};

scwin.btn_getText4_onclick = function (e) {
    scwin.get_text(target4);
}


// target5 (maxByteLength=6 + maxlength=3 → 같은 byte 길이일 때 maxByteLength 적용)
// 한글 3자 = 6byte, maxlength 3 = 한글 3자 가능. 같은 값이면 maxByteLength 적용 (byte 기준)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가나다라마바");
    target5.focus();
};

scwin.btn_getText5_onclick = function (e) {
    scwin.get_text(target5);
}


// target6 (maxByteLength=6, validate 실패 → invalidMessage 출력)
// setValue 후 즉시 validate() 호출 시 oneditend 미발생으로 잘림 미적용 → FAIL 정상 발생
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("가나다라");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.btn_setValue6_onclick();
    scwin.check_validate(target6);
}


// target7 (maxByteLength=6, validate 실패 → 시스템 기본 메시지 출력)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("가나다라");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.btn_setValue7_onclick();
    scwin.check_validate(target7);
}


// target8 (maxByteLength=6, validate 실패 → invalidMessageFunc 메시지 출력)
scwin.btn_setValue8_onclick = function (e) {
    target8.setValue("가나다라");
};

scwin.btn_validate8_onclick = function (e) {
    scwin.btn_setValue8_onclick();
    scwin.check_validate(target8);
}


// target9 (maxByteLength=6, oneditfull 이벤트 핸들러 등록)
// oneditfull 발생 조건 (textarea.js handleKeyupEvent):
//   1) byteLength == maxByteLength AND 마지막 글자가 한글이 아닐 것
//   2) byteLength > maxByteLength (초과, 자동 자르기로 일반 입력에서는 거의 미발생)
// → "가나다" (6byte, 마지막 한글) 입력 시 조건1 미충족(마지막 한글) + 조건2 미충족 → 이벤트 미발생.
// → "abcdef" (6byte, 마지막 영문) 입력 시 조건1 충족 → 이벤트 발생.
// setValue 만으로는 keyup 이벤트가 안 일어나므로 keyup 을 직접 dispatch 하여 도달 검사 경로 트리거.
scwin.btn_setValue9_onclick = function (e) {
    target9.setValue("abcdef");
    target9.focus();
    target9.render.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, keyCode: 70 }));
};

scwin.btn_getText9_onclick = function (e) {
    scwin.get_text(target9);
}


// oneditfull 이벤트 핸들러
scwin.target9_oneditfull = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("oneditfull event fired (maxByteLength reached)");
}


// invalidMessageFunc 사용자 정의 함수
scwin.fn_msg = function () {
    let invalidType = this.getType();
    let invalidValue = this.getValue();
    let msg = "Not valid.";

    if (invalidType === "maxByteLength") {
        msg = "사용자 정의 메시지: 최대 " + invalidValue + " byte 초과";
    }
    return msg;
}
